318	    public static String normalizeAddress(String value) {
319	        if (value == null) {
320	            return "";
321	        }
322	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
323	        if (collapsed.isEmpty()) {
324	            return "";
325	        }
326	        String[] tokens = collapsed.split(" ");
327	        for (int i = 0; i < tokens.length; i++) {
328	            tokens[i] = switch (tokens[i]) {
329	                case "ST" -> "STREET";
330	                case "RD" -> "ROAD";
331	                case "AVE" -> "AVENUE";
332	                default -> tokens[i];
333	            };
334	        }
335	        return String.join(" ", tokens);
336	    }
